# Generated by Cake for FlashInfer. Exporter output, hand-edited here pending
# exporter support. The export rendered one positional launcher per program from
# its frozen argument plan; this module derives the same launchers from
# ``PROGRAMS[program]["arg_plan"]`` at import.  ``LAUNCH[program](run, values,
# grid)`` calls the binding entry ``run`` with ``values[<kernel argument>]`` for
# every slot of the plan that is not a grid slot, in plan order, followed by the
# grid triple (the plan's trailing three slots ``grid_x``, ``grid_y``, ``grid_z``).

from __future__ import annotations

from typing import Any, Callable

from .cake_jit import PROGRAMS

Launcher = Callable[[Callable[..., Any], dict[str, Any], tuple[int, int, int]], None]


def _positional(plan: list[list[str]]) -> Launcher:
    """The positional launcher of one argument plan: ``values[name]`` for every slot
    whose kind is not ``grid``, in plan order, then the grid triple."""
    names = [name for kind, name in plan if kind != "grid"]

    def launch(
        run: Callable[..., Any], values: dict[str, Any], grid: tuple[int, int, int]
    ) -> None:
        run(*[values[name] for name in names], *grid)

    return launch


LAUNCH: dict[str, Launcher] = {
    program: _positional(record["arg_plan"]) for program, record in PROGRAMS.items()
}
